import { useState, ChangeEvent, KeyboardEvent } from 'react';
import { Tag, TextInput } from '@jinx-ui/react';

interface TagPickerProps {
  initialTags?: string[];
  placeholder?: string;
  onChange: (tags: string[]) => void;
}

const TagPicker = ({
  initialTags = [],
  placeholder = 'Добавьте тег и нажмите Enter',
  onChange,
}: TagPickerProps) => {
  const [tags, setTags] = useState<string[]>(initialTags);
  const [draft, setDraft] = useState('');

  const commitTags = (nextTags: string[]) => {
    setTags(nextTags);
    onChange(nextTags);
  };

  const addTagFromDraft = () => {
    const normalized = draft.trim();
    if (normalized.length === 0) {
      return;
    }
    const alreadyExists = tags.some(
      (tag) => tag.toLowerCase() === normalized.toLowerCase()
    );
    if (!alreadyExists) {
      commitTags([...tags, normalized]);
    }
    setDraft('');
  };

  const removeTag = (tagToRemove: string) => {
    commitTags(tags.filter((tag) => tag !== tagToRemove));
  };

  const handleInputChange = (event: ChangeEvent<HTMLInputElement>) => {
    setDraft(event.target.value);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTagFromDraft();
      return;
    }
    if (event.key === 'Backspace' && draft.length === 0 && tags.length > 0) {
      commitTags(tags.slice(0, -1));
    }
  };

  return (
    <div
      className="jx-tag-picker"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}
    >
      <TextInput
        className="jx-tag-picker__input"
        value={draft}
        placeholder={placeholder}
        onChange={handleInputChange}
        onKeyDown={handleKeyDown}
        aria-label="Новый тег"
      />
      <div
        className="jx-tag-picker__list"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-1)' }}
      >
        {tags.map((tag) => (
          <Tag key={tag} className="jx-tag-picker__tag" onRemove={() => removeTag(tag)}>
            {tag}
          </Tag>
        ))}
      </div>
    </div>
  );
};

export default TagPicker;

